echo "=== recommendation-related enums in schema.json ==="
python3 - <<'EOF'
import json
s=json.load(open('schema.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        if 'enum' in o and isinstance(o['enum'],list):
            print(p,'->',o['enum'])
        for k,v in o.items(): walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,p+f'/{i}')
walk(s)
EOF
